/** Verifies the health response, local CORS policy, and method restrictions. */
test("health endpoint responds successfully to the local frontend", async (context) => {
  const server = createServer();
  server.listen(0, "127.0.0.1");
  await once(server, "listening");

  /** Closes the ephemeral server after the test. */
  async function closeServer() {
    server.close();
    await once(server, "close");
  }

  context.after(closeServer);

  const baseUrl = `http://127.0.0.1:${server.address().port}`;
  const response = await fetch(`${baseUrl}/health`, {
    headers: { Origin: "http://127.0.0.1:5173" },
  });
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: "ok" });
  assert.equal(response.headers.get("access-control-allow-origin"), "http://127.0.0.1:5173");
  assert.equal(response.headers.get("x-content-type-options"), "nosniff");

  const rejectedOriginResponse = await fetch(`${baseUrl}/health`, {
    headers: { Origin: "https://example.invalid" },
  });
  assert.equal(rejectedOriginResponse.headers.get("access-control-allow-origin"), null);

  const rejectedMethodResponse = await fetch(`${baseUrl}/health`, { method: "POST" });
  assert.equal(rejectedMethodResponse.status, 405);
});

